int i = 10;
float* fp;
void* vp;

// 1. static_cast (Compile-time known conversions)
// Prefer over C-style for safe numeric/pointer conversions

float f_cstyle = (float)i;

float f_static = static_cast<float>(i);
int* i_ptr = static_cast<int*>(vp); // Void pointer conversion

// 2. const_cast (Only for const/volatile management)
const int V = 5;
const int* ptr_cv = &V;
int* ptr_nc = const_cast<int*>(ptr_cv);


// 3. reinterpret_cast (Bit-level, dangerous pointer conversions)
// Often used for serialization/hardware interaction
char buffer[4];
int* int_ptr = reinterpret_cast<int*>(buffer);


// 4. dynamic_cast (Runtime safe polymorphic downcasting)
class Base { public: virtual ~Base() {} };
class Derived : public Base {};

Base* b = new Derived;
Derived* d = dynamic_cast<Derived*>(b); // nullptr if fails
delete b;
